import type { ReactNode } from 'react'

import {
  BrowserChrome,
  DemoStage,
  DockHeader,
  mockImage,
  Toggle,
  type Build,
} from '@/app/demos/stage'

import { CAPTIONS, LABELS, OUTLINE } from './script'

const CLEAR = 'rgba(239, 68, 68, 0)'
const ACCENT = 'rgba(99, 102, 241, 0.85)'

const build: Build = ({ tl, q, qa, step, final, move, click, wait, cursorOut }) => {
  const hover = (d: string, ax = 0.5) => {
    move(d, { ax, duration: 0.6 })
    tl.set(q('hover-ring'), { opacity: 0, duration: 0.01 })
    tl.to(q('hover-ring'), { opacity: 1, duration: 0.2 }, '>-0.05')
    tl.to(q('hover-card'), { opacity: 1, y: 0, duration: 0.25 }, '<')
  }

  tl.set(qa('wf'), { outline: `1px solid ${CLEAR}` }, 0)

  step(0)
  move('switch', { at: 0.2 })
  click('switch')
  tl.to(q('switch-fill'), { opacity: 1, duration: 0.2 }, '<')
  tl.to(q('switch-knob'), { x: 12, duration: 0.25, ease: 'back.out(2)' }, '<')

  step(1, '+=0.1')
  tl.to(qa('wf'), {
    outline: `1px solid ${OUTLINE}`,
    duration: 0.25,
    stagger: { each: 0.035, from: 'start' },
  })
  cursorOut('<')

  step(2, '+=0.4')
  hover('wf-card-1', 0.5)
  wait(0.35)
  hover('wf-cta', 0.5)
  wait(0.35)

  step(3, '+=0.2')
  hover('wf-table', 0.3)
  tl.fromTo(q('edge'), { opacity: 0 }, { opacity: 1, duration: 0.3 }, '<')
  tl.to(q('edge'), { opacity: 0.4, duration: 0.3, yoyo: true, repeat: 3 })
  cursorOut('+=0.3')
  final()
  wait(1.2)
}

function Box({
  d,
  className,
  children,
  style,
}: {
  d?: string
  className?: string
  children?: ReactNode
  style?: React.CSSProperties
}) {
  return (
    <div data-d={d ? `wf ${d}` : 'wf'} className={className} style={style}>
      {children}
    </div>
  )
}

function Page() {
  return (
    <div className="relative h-full overflow-hidden bg-[#fafafa] text-[#111]">
      <Box className="flex items-center gap-3 border-b border-black/5 px-4 py-2.5">
        <Box className="flex items-center gap-1.5 text-[11px] font-semibold">
          <Box className="size-3 rounded bg-[#111]" />
          Northwind
        </Box>
        <Box className="ml-auto flex gap-3 text-[9.5px] text-[#555]">
          <Box>Product</Box>
          <Box>Pricing</Box>
        </Box>
      </Box>
      <Box className="px-4 pt-3">
        <Box className="text-[16px] font-bold tracking-tight">Plans for every team</Box>
        <Box className="mt-1 text-[9px] text-[#555]">Start free, upgrade when you grow.</Box>
        <Box
          d="wf-cta"
          className="mt-2 w-fit rounded-md bg-[#7c3aed] px-3 py-1.5 text-[9.5px] font-medium text-white"
        >
          Start free
        </Box>
        <Box className="mt-3 grid grid-cols-3 gap-2">
          {[0, 1, 2].map((index) => (
            <Box
              key={index}
              d={`wf-card-${index}`}
              className="rounded-lg border border-black/5 bg-white p-1.5 shadow-sm"
            >
              <Box className="h-9 rounded-md" style={{ background: mockImage(index) }} />
              <Box className="mt-1.5 h-1.5 w-4/5 rounded-full bg-black/15" />
              <Box className="mt-1 h-1.5 w-1/2 rounded-full bg-black/10" />
            </Box>
          ))}
        </Box>
        <Box
          d="wf-table"
          className="mt-3 flex w-[125%] gap-2 rounded-md border border-black/5 bg-white p-1.5 text-[8.5px] text-[#555]"
        >
          {['Seats', 'Storage', 'SSO', 'Audit log', 'Support'].map((cell) => (
            <Box key={cell} className="flex-1 rounded bg-black/[0.04] px-1.5 py-1">
              {cell}
            </Box>
          ))}
        </Box>
      </Box>
      <span data-d="edge" className="absolute inset-y-0 right-0 w-0.5 bg-[#0080ff] opacity-0" />
    </div>
  )
}

